# Rasterfall map v2
# world minx maxx minz maxz room_limit
# 直线型据点链：起点安全屋 -> 据点1 -> 据点2 -> 终局通道 -> 终点安全屋。
# 两个据点居中于 x -1800..1800，为完全开放的防守区；
# 全部刷怪区贴近世界四边，尸潮从远方边缘涌来。
world -12000 12000 -12000 12000 24000
start 0 -5000

# ── 起点安全屋（不变）───────────────────────────────────────────────
safe -1800 1800 -5700 -4000
floor -1800 1800 -5700 -4000 245238
box -2000 -1800 -5700 -3800 1300 3F6751
box 1800 2000 -5700 -3800 1300 3F6751
box -1800 -600 -4000 -3800 1300 3F6751
box 600 1800 -4000 -3800 1300 3F6751
box -1800 -600 -5700 -5680 1300 3F6751
box 600 1800 -5700 -5680 1300 3F6751
model -1800 1800 -5700 -4000 1300 1500 3F6751 0

# ── 开发者区（保留：测试按钮、武器桌、陈列台、贴图展示墙）──────────
# 空气墙与起点后墙同线；中心为开发者门。
box -12000 -1800 -5700 -5680 1800 000000 air
box 1800 12000 -5700 -5680 1800 000000 air
floor -12000 -1800 -5900 -5700 26394A
floor 1800 12000 -5900 -5700 26394A
label -11000 11000 -6200 -6000 70D8FF AIR WALL CONTROL LINE

